mkitem!{mkenum!{# [doc = " Type representing basic blocks."] # [doc = ""] # [doc = " All terminators will have this type as a return type. It helps achieve some type safety."] # [rustc_diagnostic_item = "mir_basic_block"] pub enum BasicBlock { # [doc = " A non-cleanup basic block."] Normal , # [doc = " A basic block that lies on an unwind path."] Cleanup , }}}
mkitem!{mkenum!{# [doc = " The reason we are terminating the process during unwinding."] # [rustc_diagnostic_item = "mir_unwind_terminate_reason"] pub enum UnwindTerminateReason { # [doc = " Unwinding is just not possible given the ABI of this function."] Abi , # [doc = " We were already cleaning up for an ongoing unwind, and a *second*, *nested* unwind was"] # [doc = " triggered by the drop glue."] InCleanup , }}}
mkuse!{pub use UnwindTerminateReason :: { Abi as ReasonAbi , InCleanup as ReasonInCleanup } ;}
mkitem!{macro_rules ! define { ($ name : literal , $ (# [$ meta : meta]) * fn $ ($ sig : tt) *) => { # [rustc_diagnostic_item = $ name] # [inline] $ (# [$ meta]) * pub fn $ ($ sig) * { panic ! () } } }}
