mkitem!{define ! ("mir_drop" , # [doc = " Drop the contents of a place."] # [doc = ""] # [doc = " The first argument must be a place."] # [doc = ""] # [doc = " The second argument must be of the form `ReturnTo(bb)`, where `bb` is the basic block that"] # [doc = " will be jumped to after the destructor returns."] # [doc = ""] # [doc = " The third argument describes what happens on unwind. It can be one of:"] # [doc = " - [`UnwindContinue`]"] # [doc = " - [`UnwindUnreachable`]"] # [doc = " - [`UnwindTerminate`]"] # [doc = " - [`UnwindCleanup`]"] fn Drop < T > (place : T , goto : ReturnToArg , unwind_action : UnwindActionArg)) ;}
