mkitem!{define ! ("mir_field" , # [doc = " Access the field with the given index of some place."] # [doc = ""] # [doc = " This only makes sense to use in conjunction with [`Variant`]. If the type you are looking to"] # [doc = " access the field of does not have variants, you can use normal field projection syntax."] # [doc = ""] # [doc = " There is no proper way to do a place projection to a variant in Rust, and so these two"] # [doc = " functions are a workaround. You can access a field of a variant via `Field(Variant(place,"] # [doc = " var_idx), field_idx)`, where `var_idx` and `field_idx` are appropriate literals. Some"] # [doc = " caveats:"] # [doc = ""] # [doc = "  - The return type of `Variant` is always `()`. Don't worry about that, the correct MIR will"] # [doc = "    still be generated."] # [doc = "  - In some situations, the return type of `Field` cannot be inferred. You may need to"] # [doc = "    annotate it on the function in these cases."] # [doc = "  - Since `Field` is a function call which is not a place expression, using this on the left"] # [doc = "    hand side of an expression is rejected by the compiler. [`place!`] is a macro provided to"] # [doc = "    work around that issue. Wrap the left hand side of an assignment in the macro to convince"] # [doc = "    the compiler that it's ok."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " #![allow(internal_features)]"] # [doc = " #![feature(custom_mir, core_intrinsics)]"] # [doc = ""] # [doc = " use core::intrinsics::mir::*;"] # [doc = ""] # [doc = " #[custom_mir(dialect = \"built\")]"] # [doc = " fn unwrap_deref(opt: Option<&i32>) -> i32 {"] # [doc = "     mir! {"] # [doc = "         {"] # [doc = "             RET = *Field::<&i32>(Variant(opt, 1), 0);"] # [doc = "             Return()"] # [doc = "         }"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " #[custom_mir(dialect = \"built\")]"] # [doc = " fn set(opt: &mut Option<i32>) {"] # [doc = "     mir! {"] # [doc = "         {"] # [doc = "             place!(Field(Variant(*opt, 1), 0)) = 5;"] # [doc = "             Return()"] # [doc = "         }"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] fn Field < F > (place : () , field : u32) -> F) ;}
mkitem!{define ! ("mir_variant" , # [doc = " Adds a variant projection with the given index to the place."] # [doc = ""] # [doc = " See [`Field`] for documentation."] fn Variant < T > (place : T , index : u32) -> ()) ;}
mkitem!{define ! ("mir_cast_transmute" , # [doc = " Emits a `CastKind::Transmute` cast."] # [doc = ""] # [doc = " Needed to test the UB when `sizeof(T) != sizeof(U)`, which can't be"] # [doc = " generated via the normal `mem::transmute`."] fn CastTransmute < T , U > (operand : T) -> U) ;}
