mkitem!{# [doc = " Macro for generating custom MIR."] # [doc = ""] # [doc = " See the module documentation for syntax details. This macro is not magic - it only transforms"] # [doc = " your MIR into something that is easier to parse in the compiler."] # [rustc_macro_transparency = "transparent"] pub macro mir { { $ (type RET = $ ret_ty : ty ;) ? $ (let $ local_decl : ident $ (: $ local_decl_ty : ty) ? ;) * $ (debug $ dbg_name : ident => $ dbg_data : expr ;) * { $ ($ entry : tt) * } $ ($ block_name : ident $ (($ block_cleanup : ident)) ? = { $ ($ block : tt) * }) * } => { { __internal_declare_basic_blocks ! ($ ($ block_name $ (($ block_cleanup)) ?) *) ; { # [allow (non_snake_case)] let RET $ (: $ ret_ty) ?; $ (let $ local_decl $ (: $ local_decl_ty) ? ;) * :: core :: intrinsics :: mir :: __internal_extract_let ! ($ ($ entry) *) ; $ (:: core :: intrinsics :: mir :: __internal_extract_let ! ($ ($ block) *) ;) * { $ (__debuginfo (stringify ! ($ dbg_name) , $ dbg_data) ;) * { :: core :: intrinsics :: mir :: __internal_remove_let ! ({ { } { $ ($ entry) * } }) ; $ (:: core :: intrinsics :: mir :: __internal_remove_let ! ({ { } { $ ($ block) * } }) ;) * RET } } } } } }}
mkitem!{# [doc = " Helper macro that allows you to treat a value expression like a place expression."] # [doc = ""] # [doc = " See the documentation on [`Variant`] for why this is necessary and how to use it."] pub macro place ($ e : expr) { (*:: core :: intrinsics :: mir :: __internal_make_place ($ e)) }}
mkitem!{# [doc = " Helper macro that extracts the `let` declarations out of a bunch of statements."] # [doc = ""] # [doc = " This macro is written using the \"statement muncher\" strategy. Each invocation parses the first"] # [doc = " statement out of the input, does the appropriate thing with it, and then recursively calls the"] # [doc = " same macro on the remainder of the input."] # [doc (hidden)] pub macro __internal_extract_let { (let $ var : ident $ (: $ ty : ty) ? = $ expr : expr ; $ ($ rest : tt) *) => { let $ var $ (: $ ty) ?; :: core :: intrinsics :: mir :: __internal_extract_let ! ($ ($ rest) *) ; } , (let $ var : ident $ (: $ ty : ty) ? = const $ block : block ; $ ($ rest : tt) *) => { let $ var $ (: $ ty) ?; :: core :: intrinsics :: mir :: __internal_extract_let ! ($ ($ rest) *) ; } , ($ stmt : stmt ; $ ($ rest : tt) *) => { :: core :: intrinsics :: mir :: __internal_extract_let ! ($ ($ rest) *) ; } , ($ expr : expr) => { } }}
mkitem!{# [doc = " Helper macro that removes the `let` declarations from a bunch of statements."] # [doc = ""] # [doc = " Because expression position macros cannot expand to statements + expressions, we need to be"] # [doc = " slightly creative here. The general strategy is also statement munching as above, but the output"] # [doc = " of the macro is \"stored\" in the subsequent macro invocation. Easiest understood via example:"] # [doc = " ```text"] # [doc = " invoke!("] # [doc = "     {"] # [doc = "         {"] # [doc = "             x = 5;"] # [doc = "         }"] # [doc = "         {"] # [doc = "             let d = e;"] # [doc = "             Call()"] # [doc = "         }"] # [doc = "     }"] # [doc = " )"] # [doc = " ```"] # [doc = " becomes"] # [doc = " ```text"] # [doc = " invoke!("] # [doc = "     {"] # [doc = "         {"] # [doc = "             x = 5;"] # [doc = "             d = e;"] # [doc = "         }"] # [doc = "         {"] # [doc = "             Call()"] # [doc = "         }"] # [doc = "     }"] # [doc = " )"] # [doc = " ```"] # [doc (hidden)] pub macro __internal_remove_let { ({ { $ ($ already_parsed : tt) * } { let $ var : ident $ (: $ ty : ty) ? = $ expr : expr ; $ ($ rest : tt) * } }) => { :: core :: intrinsics :: mir :: __internal_remove_let ! ({ { $ ($ already_parsed) * $ var = $ expr ; } { $ ($ rest) * } }) } , ({ { $ ($ already_parsed : tt) * } { let $ var : ident $ (: $ ty : ty) ? = const $ block : block ; $ ($ rest : tt) * } }) => { :: core :: intrinsics :: mir :: __internal_remove_let ! ({ { $ ($ already_parsed) * $ var = const $ block ; } { $ ($ rest) * } }) } , ({ { $ ($ already_parsed : tt) * } { $ stmt : stmt ; $ ($ rest : tt) * } }) => { :: core :: intrinsics :: mir :: __internal_remove_let ! ({ { $ ($ already_parsed) * $ stmt ; } { $ ($ rest) * } }) } , ({ { $ ($ already_parsed : tt) * } { $ expr : expr } }) => { { $ ($ already_parsed) * $ expr } } , }}
mkitem!{# [doc = " Helper macro that declares the basic blocks."] # [doc (hidden)] pub macro __internal_declare_basic_blocks { () => { } , ($ name : ident (cleanup) $ ($ rest : tt) *) => { let $ name = :: core :: intrinsics :: mir :: BasicBlock :: Cleanup ; __internal_declare_basic_blocks ! ($ ($ rest) *) } , ($ name : ident $ ($ rest : tt) *) => { let $ name = :: core :: intrinsics :: mir :: BasicBlock :: Normal ; __internal_declare_basic_blocks ! ($ ($ rest) *) } , }}